using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ── CalculateTotal: DataRow-driven tests ────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0,  10.00,  DisplayName = "Single item, no tax")]
    [DataRow(10.00, 5, 0.0,  50.00,  DisplayName = "Multiple items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00,  DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62,  DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00,  5, 0.10, 0.00,   DisplayName = "Zero unit price")]
    [DataRow(10.00, 0, 0.10, 0.00,   DisplayName = "Zero quantity")]
    [DataRow(99.99, 1, 1.0,  199.98, DisplayName = "Max tax rate (100%)")]
    public void CalculateTotal_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    // ── CalculateTotal: DynamicData from method ─────────────────────────

    public static IEnumerable<object[]> InvalidCalculateTotalInputs =>
    [
        [/* unitPrice */ -1m, /* qty */ 1,  /* tax */ 0.1m, /* param */ "unitPrice"],
        [/* unitPrice */  5m, /* qty */ -1, /* tax */ 0.1m, /* param */ "quantity"],
        [/* unitPrice */  5m, /* qty */ 1,  /* tax */ -0.1m,/* param */ "taxRate"],
        [/* unitPrice */  5m, /* qty */ 1,  /* tax */ 1.1m, /* param */ "taxRate"],
    ];

    [TestMethod]
    [DynamicData(nameof(InvalidCalculateTotalInputs))]
    public void CalculateTotal_InvalidInput_Throws(
        decimal unitPrice, int quantity, decimal taxRate, string expectedParamName)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(unitPrice, quantity, taxRate));

        Assert.AreEqual(expectedParamName, ex.ParamName);
    }

    // ── ApplyDiscount: DataRow-driven tests ─────────────────────────────

    [TestMethod]
    [DataRow(100.00, 0.0,   100.00, DisplayName = "No discount")]
    [DataRow(100.00, 10.0,  90.00,  DisplayName = "10% discount")]
    [DataRow(100.00, 50.0,  50.00,  DisplayName = "50% discount")]
    [DataRow(100.00, 100.0, 0.00,   DisplayName = "100% discount (free)")]
    [DataRow(49.99,  25.0,  37.4925,DisplayName = "Fractional result")]
    [DataRow(0.00,   50.0,  0.00,   DisplayName = "Zero price, any discount")]
    public void ApplyDiscount_ReturnsExpected(
        double price, double discountPercent, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent);

        Assert.AreEqual((decimal)expected, result);
    }

    // ── ApplyDiscount: DynamicData from method ──────────────────────────

    public static IEnumerable<object[]> InvalidDiscountInputs =>
    [
        [100m, -1m],
        [100m, 101m],
    ];

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountInputs))]
    public void ApplyDiscount_InvalidDiscount_Throws(
        decimal price, decimal discountPercent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discountPercent));
    }

    // ── FormatPrice: DataRow-driven tests ───────────────────────────────

    [TestMethod]
    [DataRow(19.99, "$", "$19.99", DisplayName = "USD format")]
    [DataRow(19.99, "€", "€19.99", DisplayName = "EUR format")]
    [DataRow(5.00,  "$", "$5.00",  DisplayName = "Whole number padded")]
    [DataRow(0.00,  "$", "$0.00",  DisplayName = "Zero price")]
    public void FormatPrice_ReturnsExpected(
        double price, string symbol, string expected)
    {
        var result = _calculator.FormatPrice((decimal)price, symbol);

        Assert.AreEqual(expected, result);
    }
}

